 Label LabelAt(string text,int x,int y,int width,int height,float size,Color color){return new Label{Text=text,Location=new Point(x,y),Size=new Size(width,height),ForeColor=color,Font=new Font("Segoe UI",size),BackColor=Color.Transparent,UseMnemonic=false};}
 Button HelpAt(int x,int y,string title,string body){var b=new Button{Text="?",Location=new Point(x,y),Size=new Size(26,26),FlatStyle=FlatStyle.Flat,ForeColor=Orange,BackColor=Card,AccessibleName="Help: "+title,AccessibleDescription=body};b.FlatAppearance.BorderColor=Edge;RegisterHint(b,"Help: "+title+".\nPress Enter or click for details.");b.Click+=(a,e)=>OpenHelp(title,body);return b;}
 Control FutureCard(string title,string caption,string help){var p=new Panel{Dock=DockStyle.Fill,BackColor=Card,Margin=new Padding(0,0,0,8)};var name=LabelAt(title,12,8,260,22,11,Paper);var state=LabelAt("PLANNED / FUTURE VERSION",12,32,275,17,8,Orange);var desc=LabelAt(caption,12,51,290,17,8,Quiet);p.Controls.Add(name);p.Controls.Add(state);p.Controls.Add(desc);var q=HelpAt(285,7,title,help);q.Anchor=AnchorStyles.Top|AnchorStyles.Left;p.Controls.Add(q);p.SizeChanged+=(a,e)=>q.Location=new Point(p.ClientSize.Width-38,7);string brief="Planned / future version.\nClick ? for "+title.ToLowerInvariant()+" details.";RegisterHint(p,brief);RegisterHint(name,brief);RegisterHint(state,brief);RegisterHint(desc,brief);name.Click+=(a,e)=>q.PerformClick();p.AccessibleName=title+" planned, help only";return p;}
 void UpdateKeyState(){if(IsDisposed||Disposing)return;bool installed=keySession!=null&&keySession.Installed;keyToggle.Text=installed?"Stop key blocking":"Block key + close Copilot app";keyState.Text=installed?"KEY · Hook installed (OS reported) · session only":keySession!=null&&keySession.Error!=null?"KEY · Failed / stopped — see help or retry":"KEY · Off — no hook installed";}
 void InspectCopilot(){HideHint();if(preview)return;try{string diagnostic;var targets=CopilotApp.Preview(out diagnostic);var text=new System.Text.StringBuilder();text.AppendLine("Verified targets: "+targets.Count);foreach(var target in targets)text.AppendLine(target.Name+" #"+target.Id+" | "+target.Reason);text.AppendLine(diagnostic);using(var dialog=new HelpDialog("Copilot process diagnostics · read-only",text.ToString()))dialog.ShowDialog(this);}catch(Exception e){MessageBox.Show(this,e.Message,"Copilot diagnostics failed");}}
 void ToggleKey(){if(preview)return;HideHint();try{if(keySession!=null&&keySession.Installed){keySession.Dispose();keySession=null;}else{string limits;List<CopilotTarget> targets;try{targets=CopilotApp.Preview(out limits);}catch(Exception detection){targets=new List<CopilotTarget>();limits="Copilot detection failed: "+detection.Message+". Only key blocking can be enabled; no process termination will be attempted.";}var review=new System.Text.StringBuilder();foreach(var target in targets)review.AppendLine(target.Name+" #"+target.Id+" | "+target.Reason);using(var confirmation=new HelpDialog("Review Copilot app close","Enable key blocking and force-close these verified Copilot processes? Unsaved app state may be lost and cannot be restored. Only reviewed identities will be targeted.\r\n\r\n"+review+"\r\n"+limits,true)){if(confirmation.ShowDialog(this)!=DialogResult.OK)return;}string closed=targets.Count==0?"No verified Copilot targets; no process was force-closed. Key blocking can still run. Use Inspect Copilot for details.":CopilotApp.CloseReviewed(targets);using(var results=new HelpDialog("Copilot close results",closed+"\r\n"+limits))results.ShowDialog(this);if(keySession!=null){keySession.Dispose();keySession=null;}keySession=new CopilotKeySession();keySession.Changed+=()=>{if(IsHandleCreated&&!IsDisposed)try{BeginInvoke((Action)UpdateKeyState);}catch{}};keySession.Start();}}catch(Exception e){MessageBox.Show(this,e.Message,"Copilot key profile",MessageBoxButtons.OK,MessageBoxIcon.Warning);}UpdateKeyState();}
 void StopKey(){if(keySession==null)return;keySession.Dispose();keySession=null;} void RegisterHint(Control target,string brief){target.MouseEnter+=(a,e)=>ShowHint(target,brief);target.MouseLeave+=(a,e)=>HideHint();target.Enter+=(a,e)=>ShowHint(target,brief);target.Leave+=(a,e)=>HideHint();target.Disposed+=(a,e)=>HideHint();}
 void ShowHint(Control target,string brief){if(IsDisposed||Disposing||!ContainsFocus)return;if(hintBox==null){hintBox=new Panel{BackColor=Edge,Size=new Size(340,68),Padding=new Padding(10),Visible=false,TabStop=false};hintText=new Label{Dock=DockStyle.Fill,ForeColor=Paper,BackColor=Edge,Font=new Font("Segoe UI",9),UseMnemonic=false,AutoSize=false,TextAlign=ContentAlignment.MiddleLeft};hintBox.Controls.Add(hintText);Controls.Add(hintBox);}hintText.Text=brief;Point point=PointToClient(target.PointToScreen(new Point(0,target.Height+4)));point.X=Math.Max(8,Math.Min(point.X,ClientSize.Width-hintBox.Width-8));point.Y=Math.Max(8,Math.Min(point.Y,ClientSize.Height-hintBox.Height-8));hintBox.Location=point;hintBox.Visible=true;hintBox.BringToFront();}
 void HideHint(){if(hintBox!=null&&!hintBox.IsDisposed)hintBox.Visible=false;}
 void OpenHelp(string title,string body){HideHint();try{using(var help=new HelpDialog(title,body)){help.ShowDialog(this);}}finally{HideHint();}}
 protected override void OnDeactivate(EventArgs e){HideHint();base.OnDeactivate(e);}
 protected override void OnResize(EventArgs e){HideHint();base.OnResize(e);}
 protected override void OnFormClosing(FormClosingEventArgs e){HideHint();try{StopKey();}catch(Exception x){if(!preview)MessageBox.Show(this,x.Message,"Hook shutdown",MessageBoxButtons.OK,MessageBoxIcon.Warning);}base.OnFormClosing(e);}
 protected override void Dispose(bool disposing){if(disposing){HideHint();try{StopKey();}catch{}}base.Dispose(disposing);} void UpdateSummary(){try{var capture=Engine.Capture();var active=capture.FindAll(a=>a.State==1);bool unsupported=false,unmuted=false;foreach(var a in active){unsupported|=(Engine.Hardware(a.Id)&2)==0;unmuted|=!Engine.Muted(a.Id);}micState.Text=active.Count==0?"MIC · No active capture endpoint":unsupported?"MIC · Unsupported hardware mute":unmuted?"MIC · Available / not hardware-muted":"MIC · Hardware mute confirmed by driver";micState.ForeColor=unmuted||unsupported?Orange:Paper;}catch{micState.Text="MIC · Verification unavailable";micState.ForeColor=Orange;}try{var cameras=Engine.Inventory().FindAll(d=>d.Class=="Camera");cameraState.Text=cameras.Count==0?"CAM · No supported camera found":cameras.Exists(d=>d.Problem==0)?"CAM · Camera enabled":cameras.TrueForAll(d=>d.Problem==22)?"CAM · Disabled status confirmed":"CAM · Partial / driver issue";}catch{cameraState.Text="CAM · Verification unavailable";}if(preview){Text="Privacy Switch · SIMULATED UI PREVIEW";report.Text="SIMULATED PREVIEW — no device changes\r\n\r\n"+report.Text;}}
 static Button FindHelp(Control root,string name){foreach(Control child in root.Controls){var button=child as Button;if(button!=null&&button.AccessibleName==name)return button;var found=FindHelp(child,name);if(found!=null)return found;}return null;}
 public static int VerifyHelpLayout(){try{string folder=Path.Combine(Environment.CurrentDirectory,"work");Directory.CreateDirectory(folder);RenderPreview(Path.Combine(folder,"ui-test.png"));using(var w=new Window()){w.preview=true;w.Opacity=0;w.ShowInTaskbar=false;w.Show();Application.DoEvents();var eraseHelp=FindHelp(w,"Help: Secure erase / disposal");if(eraseHelp==null||!eraseHelp.AccessibleDescription.Contains("INFORMATION ONLY")||!eraseHelp.AccessibleDescription.Contains("irreversible"))throw new Exception("Planned erase help missing");w.ShowHint(w.toggle,"Planned / future version.\nClick ? for bounded details.");if(w.hintBox==null)throw new Exception("Hint not constructed");if(w.hintBox.Width>340||w.hintBox.Height>68||!w.ClientRectangle.Contains(w.hintBox.Bounds))throw new Exception("Hint exceeds app bounds");w.OnDeactivate(EventArgs.Empty);if(w.hintBox.Visible)throw new Exception("Deactivate did not hide hint");w.ShowHint(w.toggle,"Short focus hint");w.OnResize(EventArgs.Empty);if(w.hintBox.Visible)throw new Exception("Resize did not hide hint");w.ShowHint(w.toggle,"Short close hint");w.OnFormClosing(new FormClosingEventArgs(CloseReason.UserClosing,false));if(w.hintBox.Visible)throw new Exception("Closing did not hide hint");using(var help=new HelpDialog("Optional AI access",new string('x',4000))){help.Owner=w;if(help.ClientSize.Width>600||help.ClientSize.Height>440)throw new Exception("Help bounds");if(!help.Details.WordWrap||help.Details.ScrollBars!=ScrollBars.Vertical)throw new Exception("Full help does not wrap/scroll");if(help.Owner!=w||help.CancelButton==null)throw new Exception("Help ownership/escape");help.Opacity=0;help.ShowInTaskbar=false;help.Show();Application.DoEvents();using(var bitmap=new Bitmap(help.Width,help.Height)){help.DrawToBitmap(bitmap,new Rectangle(Point.Empty,help.Size));bitmap.Save(Path.Combine(folder,"help-layout-test.png"));}help.Close();}Panel hint=w.hintBox;using(var owned=new HelpDialog("Owner close test","Bounded owned help")){owned.Opacity=0;owned.ShowInTaskbar=false;owned.Show(w);Application.DoEvents();w.Dispose();if(!owned.IsDisposed)throw new Exception("Owned help survived app disposal");}if(!hint.IsDisposed)throw new Exception("Hint survived owner disposal");}return 0;}catch(Exception x){File.WriteAllText(Path.Combine(Environment.CurrentDirectory,"work","ui-test-error.txt"),x.ToString());return 1;}}

 public static int RenderPreview(string path){Application.EnableVisualStyles();Engine.Root=Path.Combine(Environment.CurrentDirectory,"work","ui-preview-unused");Engine.Inventory=()=>new List<Device>{new Device{Id="camera-example",Name="Integrated Camera (example)",Class="Camera",Problem=0,Selected=true,Manufacturer="Example driver",Driver="UI simulation"},new Device{Id="SWD\\MMDEVAPI\\{0.0.1.00000000}.example",Name="Microphone Array (example)",Class="AudioEndpoint",Problem=0,Selected=true,Manufacturer="Example driver",Driver="UI simulation"}};Engine.Capture=()=>new List<CaptureState>{new CaptureState{Id="{0.0.1.00000000}.example",State=1}};Engine.Hardware=id=>3;Engine.Muted=id=>false;using(var w=new Window()){w.preview=true;w.ShowInTaskbar=false;w.Opacity=0;w.Show();Application.DoEvents();w.RefreshReport();w.PerformLayout();using(var bitmap=new Bitmap(w.Width,w.Height)){w.DrawToBitmap(bitmap,new Rectangle(Point.Empty,w.Size));bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}return 0;}

 void RefreshReport(){toggle.Text=File.Exists(Engine.FilePath)?"Restore original mic / camera states":"Mute microphones / disable cameras";var b=new System.Text.StringBuilder();b.AppendLine("MICROPHONE & CAMERA SWITCH — Windows backend r2\r\n");b.AppendLine("OS: "+Compatibility.OS()+"\r\n");b.AppendLine("Hardware microphone mute and supported camera disable only.");b.AppendLine("Microphone mute is verified by driver readback; effective recording cutoff remains UNTESTED.");b.AppendLine("Restore preserves prior mute and disabled states. Software-only microphone mute is unsupported.");b.AppendLine("Review targets below. Administrator permission is requested for changes.\r\n");b.AppendLine("Legacy Image-class devices are listed for review, not automatically disabled.");try{foreach(var d in Engine.Inventory())if(d.Selected||d.Class=="Image")b.AppendLine((d.Selected?"TARGET  ":"UNSUPPORTED / REVIEW  ")+d.Name+" | "+d.Class+" | "+(d.Problem==22?"disabled":d.Problem==0?"enabled":"problem "+d.Problem)+"\r\n        "+d.Id+"\r\n        Driver: "+d.Manufacturer+" | "+d.Driver);}catch(Exception x){b.AppendLine("INVENTORY FAILED: "+x.Message);}try{b.AppendLine("\r\nREAD-ONLY AUDIO DRIVER METADATA (shared controllers are never changed)");foreach(var d in Engine.Inventory())if(d.Class.Equals("MEDIA",StringComparison.OrdinalIgnoreCase))b.AppendLine(d.Name+" | "+d.Manufacturer+" | "+d.Driver);}catch(Exception x){b.AppendLine("Driver metadata unavailable: "+x.Message);}try{b.AppendLine("\r\nCORE AUDIO CAPTURE AUDIT");foreach(var a in Engine.Capture()){if(a.State!=1){b.AppendLine(a.Id+" | "+CoreAudio.Describe(a.State)+" | skipped (inactive)");continue;}uint mask=Engine.Hardware(a.Id);b.AppendLine(a.Id+" | "+CoreAudio.Describe(a.State)+" | hardware support mask="+mask+" | "+((mask&2)==0?"UNSUPPORTED hardware mute":Engine.Muted(a.Id)?"driver reports hardware-muted; live cutoff unverified":"NOT MUTED; capture available"));}}catch(Exception x){b.AppendLine("CORE AUDIO VERIFICATION FAILED: "+x.Message);}if(File.Exists(Engine.FilePath))try{b.AppendLine("\r\nRECOVERY AUDIT (restrictions may be partial)");foreach(var e in Engine.Load().Entries)b.AppendLine(e.Name+": "+e.Result+" | restore pending="+e.Pending);}catch(Exception x){b.AppendLine("RECOVERY ERROR: "+x.Message);}report.Text=b.ToString();UpdateSummary();}
 void Action(){if(preview)return;bool restore=File.Exists(Engine.FilePath);if(MessageBox.Show(restore?"Restore recorded microphone and camera original states?":"Apply hardware microphone mute and camera disable? Voice/video input may stop. Shared audio controllers stay untouched. Live capture cutoff must be tested; no protected status is claimed.","Review device action",MessageBoxButtons.OKCancel,MessageBoxIcon.Warning)!=DialogResult.OK)return;try{var p=Process.Start(new ProcessStartInfo(Application.ExecutablePath,restore?"--restore":"--apply"){UseShellExecute=true,Verb="runas"});p.WaitForExit();if(p.ExitCode!=0)MessageBox.Show("Action failed or was partial. Review the audit.");}catch(Exception x){MessageBox.Show(x.Message);}RefreshReport();}
 [STAThread] public static int Main(string[] args){if(args.Length>0&&args[0]=="--test-app")return CopilotApp.Tests();if(args.Length>0&&args[0]=="--test-key")return CopilotKeyTests.Run();if(args.Length>0&&args[0]=="--test-ui")return VerifyHelpLayout();if(args.Length==2&&args[0]=="--preview")return RenderPreview(args[1]);if(args.Length>0&&args[0]=="--test")return Tests.Run();if(args.Length>0){if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))return 2;try{using(var gate=new System.Threading.Mutex(false,@"Global\PrivacySwitchDeviceAction")){if(!gate.WaitOne(0))throw new Exception("Another device action is running");try{if(args[0]=="--apply")Engine.Apply();else if(args[0]=="--restore")Engine.Restore();else return 3;}finally{gate.ReleaseMutex();}}if(File.Exists(Engine.FilePath)){var j=Engine.Load();if(args[0]=="--restore"||j.Entries.Exists(e=>!e.Done))return 4;}return 0;}catch(Exception x){MessageBox.Show(x.Message,"Device helper");return 1;}}Application.EnableVisualStyles();Application.Run(new Window());return 0;}
