public sealed class HelpDialog:Form {
 public readonly TextBox Details;
 public HelpDialog(string title,string body,bool confirm=false){Text="Privacy Switch · "+title;BackColor=Window.Ink;ForeColor=Window.Paper;ClientSize=new Size(560,390);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;ShowInTaskbar=false;StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",10);AutoScaleMode=AutoScaleMode.Dpi;var area=Screen.FromPoint(Cursor.Position).WorkingArea;ClientSize=new Size(Math.Min(560,Math.Max(280,area.Width-80)),Math.Min(390,Math.Max(240,area.Height-100)));var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(18),ColumnCount=1,RowCount=3};root.RowStyles.Add(new RowStyle(SizeType.Absolute,46));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,46));Controls.Add(root);root.Controls.Add(new Label{Text=title,ForeColor=Window.Orange,Font=new Font("Segoe UI",15),Dock=DockStyle.Fill,UseMnemonic=false},0,0);Details=new TextBox{Text=body,Multiline=true,ReadOnly=true,WordWrap=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,BackColor=Window.Card,ForeColor=Window.Paper,BorderStyle=BorderStyle.None,AccessibleName=title+" help details"};root.Controls.Add(Details,0,1);var close=new Button{Text="Close",DialogResult=DialogResult.Cancel,BackColor=Window.Orange,ForeColor=Window.Ink,FlatStyle=FlatStyle.Flat,Size=new Size(96,32),Anchor=AnchorStyles.Right|AnchorStyles.Bottom};var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(0,10,0,0)};buttons.Controls.Add(close);if(confirm){close.Text="Cancel";var apply=new Button{Text="Enable key + close app",DialogResult=DialogResult.OK,BackColor=Window.Orange,ForeColor=Window.Ink,FlatStyle=FlatStyle.Flat,Size=new Size(205,32)};buttons.Controls.Add(apply);}root.Controls.Add(buttons,0,2);CancelButton=close;AcceptButton=close;}
}










